package xyz.jovanstoiljkovic.isa.services;import org.springframework.data.repository.CrudRepository;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import xyz.jovanstoiljkovic.isa.dtos.song.SongDTO;import xyz.jovanstoiljkovic.isa.models.Song;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.util.Optional;@Servicepublic class SongService extends BaseService<Song>{    public SongService(CrudRepository<Song, Long> repo) {        super(repo);    }    public Optional<Boolean> create(MultipartFile songFile, SongDTO songDTO){        Path folderPath = Paths.get(System.getProperty("user.dir"), "src", "main", "resources", "songs");        Path filePath = folderPath.resolve(songDTO.getName() + ".mp3");        songDTO.setUrl("songs/" + songDTO.getName() + ".mp3");        try{            if(!Files.exists(folderPath)) Files.createDirectories(folderPath);            songFile.transferTo(filePath.toFile());        }        catch (Exception e){            e.printStackTrace();            return Optional.of(false);        }        return Optional.of(true);    }}